/**
 * Limites de Proteção Contra Choque Elétrico conforme NR-10 e ABNT NBR 16384 / NBR 14039
 * Delimitação de Zona de Risco, Zona Controlada e Zona Livre
 */

const ShockRules = (() => {
  /**
   * Retorna os raios das zonas de choque conforme o nível de tensão
   * @param {number} vocVolts - Tensão fase-fase nominal em Volts
   */
  function getShockBoundaries(vocVolts) {
    const v = parseFloat(vocVolts) || 380;
    const vKV = v / 1000.0;

    let rr = 0.20; // Raio de Risco em metros
    let rc = 0.70; // Raio de Controle em metros

    if (vKV <= 1.0) {
      rr = 0.20;
      rc = 0.70;
    } else if (vKV <= 3.0) {
      rr = 0.22;
      rc = 1.22;
    } else if (vKV <= 6.0) {
      rr = 0.25;
      rc = 1.25;
    } else if (vKV <= 10.0) {
      rr = 0.35;
      rc = 1.35;
    } else if (vKV <= 15.0) {
      rr = 0.38;
      rc = 1.38;
    } else if (vKV <= 20.0) {
      rr = 0.40;
      rc = 1.40;
    } else if (vKV <= 30.0) {
      rr = 0.56;
      rc = 1.56;
    } else if (vKV <= 36.0) {
      rr = 0.63;
      rc = 1.63;
    } else if (vKV <= 45.0) {
      rr = 0.65;
      rc = 1.65;
    } else if (vKV <= 69.0) {
      rr = 0.80;
      rc = 1.80;
    } else if (vKV <= 110.0) {
      rr = 1.00;
      rc = 2.00;
    } else if (vKV <= 138.0) {
      rr = 1.20;
      rc = 3.20;
    } else {
      rr = 1.60;
      rc = 4.00;
    }

    return {
      voc: v,
      vocKV: vKV,
      riskRadiusM: rr,
      riskRadiusCm: rr * 100,
      controlRadiusM: rc,
      controlRadiusCm: rc * 100,
      zones: {
        risk: `Zona de Risco: raio até ${rr.toFixed(2)} m (${(rr * 100).toFixed(0)} cm)`,
        controlled: `Zona Controlada: entre ${rr.toFixed(2)} m e ${rc.toFixed(2)} m`,
        free: `Zona Livre: além de ${rc.toFixed(2)} m`
      },
      rules: [
        'Zona de Risco: Exclusiva para profissionais autorizados com capacitação e vestimentas adequadas.',
        'Zona Controlada: Acesso restrito a trabalhadores autorizados munidos de ordem de serviço.',
        'Zona Livre: Circulação liberada para trabalhadores não eletricistas.'
      ]
    };
  }

  return {
    getShockBoundaries
  };
})();

