  electrodeCards.forEach(card => {
    card.addEventListener('click', () => {
      electrodeCards.forEach(c => c.classList.remove('selected'));
      card.classList.add('selected');
      const cfg = card.getAttribute('data-config');
      document.getElementById('electrode-config-hidden').value = cfg;

      // Se for VOA ou HOA, dimensões do invólucro não se aplicam
      const encInputs = document.querySelectorAll('.enc-input');
      const isOa = cfg.endsWith('OA');
      encInputs.forEach(i => i.disabled = isOa);

      runLiveCalculation();
      showElectrodePopover(cfg);
    });
  });

