const afbEl=document.getElementById('res-afb');const iarcEl=document.getElementById('res-iarc');const iarcMinEl=document.getElementById('res-iarc-min');const cfEl=document.getElementById('res-cf');if(afbEl)afbEl.innerHTML=`${calc.finalDlaM.toFixed(2)}<span class="unit">m</span>(${(calc.finalDlaM*100).toFixed(0)}cm)`;if(iarcEl)iarcEl.innerHTML=`${calc.iarc.toFixed(2)}<span class="unit">kA</span>`;if(iarcMinEl)iarcMinEl.innerHTML=`${calc.iarcMin.toFixed(2)}<span class="unit">kA</span>`;if(cfEl)cfEl.textContent=calc.type==='ac_3p'?calc.enclosure.cf.toFixed(3):'N/A';const nomCard=document.getElementById('scenario-nominal');const redCard=document.getElementById('scenario-reduced');if(nomCard&&redCard&&calc.type==='ac_3p'){const isRed=calc.governing==='reduzida';nomCard.classList.toggle('governing-scenario',!isRed);redCard.classList.toggle('governing-scenario',isRed);document.getElementById('nom-badge').style.display=!isRed?'block':'none';document.getElementById('red-badge').style.display=isRed?'block':'none';document.getElementById('nom-energy').textContent=`${calc.nominal.eCal.toFixed(2)}cal/cm²`;document.getElementById('nom-afb').textContent=`${calc.nominal.dlaM.toFixed(2)}m`;document.getElementById('red-energy').textContent=`${calc.reduced.eCal.toFixed(2)}cal/cm²`;document.getElementById('red-afb').textContent=`${calc.reduced.dlaM.toFixed(2)}m`;}
